"""Build an offline HTML print master from the canonical plan."""
from pathlib import Path
import importlib.util, hashlib, datetime, html, json
root=Path(__file__).resolve().parent
source=root/'IMPLEMENTATION_PLAN.md'
helper=Path('/home/guoqiuyuan/.codex/skills/render-html/scripts/render_html.py')
spec=importlib.util.spec_from_file_location('renderer',helper)
mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
raw=source.read_text();digest=hashlib.sha256(source.read_bytes()).hexdigest()
body,toc=mod._render_blocks(mod.parse_blocks(raw.splitlines()),True)
stamp=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()
nav=''.join(f'<a href="#{html.escape(t["id"])}">{html.escape(t["text"])}</a>' for t in toc if t['level']==2)
css='''
:root{--ink:#213c3b;--accent:#156b63;--line:#d5e1db}*{box-sizing:border-box}body{margin:0;background:#eef3ef;color:var(--ink);font:17px/1.9 "Noto Sans CJK SC","Microsoft YaHei",sans-serif}aside{position:fixed;top:0;bottom:0;width:260px;padding:28px 22px;overflow:auto;background:#e1ece5;font-size:13px}aside strong{display:block;font-size:20px;margin-bottom:16px}aside a{display:block;padding:6px 0;text-decoration:none}main{margin-left:260px;background:#fffefa;max-width:1250px;padding:50px 58px 80px}a{color:var(--accent)}h1{font-size:36px;line-height:1.45;margin:18px 0 24px}h2{font-size:25px;line-height:1.5;margin:45px 0 20px;border-bottom:2px solid var(--line);padding-bottom:12px}h3{font-size:20px;margin-top:30px}p{margin:15px 0}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.75;margin:24px 0}th,td{text-align:left;vertical-align:top;padding:11px 12px;border:1px solid var(--line);overflow-wrap:anywhere}th{background:#e1eee6}tr:nth-child(even){background:#f3f6ef}pre{white-space:pre-wrap;word-break:break-word;background:#eaf1eb;border:1px solid var(--line);border-radius:8px;padding:22px;font:13px/1.85 "DejaVu Sans Mono","Noto Sans CJK SC",monospace}code{font-size:.88em;background:#edf2eb;padding:2px 4px}.provenance{font-size:11px;color:#5d7570;overflow-wrap:anywhere;padding:20px;border:1px solid var(--line);margin:20px 0}.eyebrow{font-size:13px;letter-spacing:2px;color:var(--accent);font-weight:bold}.roadmap{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.roadmap>div{background:#e5f0e8;border-top:4px solid var(--accent);padding:16px;font-size:15px}.roadmap small{display:block;font-size:12px;margin-top:8px}.callout{background:#fff2d7;border-left:4px solid #b98c2e;padding:18px;margin:24px 0}.cover{padding:30px 0 34px;border-bottom:3px solid var(--accent)}footer{margin-top:35px;font-size:12px;color:#5d7570}
@media(max-width:1000px){aside{position:static;width:auto;max-height:210px}main{margin:0;padding:28px}.roadmap{grid-template-columns:1fr 1fr}}
@media print{@page{size:A4;margin:16mm 13mm}body{background:#fff;font-size:10.5pt;line-height:1.75}aside{display:none}main{margin:0;padding:0;max-width:none;background:#fff}h1{font-size:26pt}h2{font-size:17pt;break-after:avoid;margin-top:28px}h3{font-size:12pt;break-after:avoid}p{orphans:3;widows:3}table{font-size:8pt;line-height:1.65}thead{display:table-header-group}th,td{padding:7px 8px}tr{break-inside:avoid}pre{font-size:8pt;padding:14px;line-height:1.7}.cover{break-after:page;min-height:235mm;border:0;padding-top:25mm}.cover h1{font-size:31pt}.roadmap{grid-template-columns:1fr 1fr;gap:15px;margin-top:30px}.roadmap>div{font-size:12pt}.provenance{font-size:8pt}.callout{font-size:11pt;margin-top:28px}a{color:inherit;text-decoration:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
'''
cover=f'''<div class="cover"><p class="eyebrow">论文方法 → 代码模块 → 可验证实验</p><h1>v5 论文创新实验<br>代码修改与实施计划</h1><p>基于现有 cascade-routing 框架<br>2026 年 10 月 13 日</p><div class="roadmap"><div>保留可信基线<small>原 Cascade Routing 受限适配</small></div><div>补齐预测与转移<small>评分、收益、近邻与联合场景</small></div><div>实现滚动规划<small>四维前沿、首动作与真实反馈</small></div><div>完成实验闭环<small>冻结、校准、E1–E6、复算</small></div></div><div class="callout">建议路线：复用执行与资源框架，新增独立 v5 方法模块。先在开发数据验证逻辑，再冻结正式策略；公开基准缓存不替代船岸云领域数据。</div><div class="provenance">来源：{html.escape(str(source))}<br>SHA256：{digest}<br>生成时间：{stamp}<br>性质：实施计划；未执行算法改造或正式实验。</div></div>'''
page=f'<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="source-path" content="{html.escape(str(source))}"><meta name="source-sha256" content="{digest}"><meta name="generated-at" content="{stamp}"><title>v5 代码修改与创新实验计划</title><style>{css}</style></head><body><aside><strong>v5 实施计划</strong>{nav}</aside><main>{cover}{body}<footer>依据本地 v5 中英文 PDF 与当前源码。由 build_pdf.py 和 render-html 解析器生成；无需网络或外部字体。</footer></main></body></html>'
(root/'V5_IMPLEMENTATION_PLAN.html').write_text(page)
(root/'build_manifest.json').write_text(json.dumps({'source':str(source),'source_sha256':digest,'generated_at':stamp,'source_h2':len([t for t in toc if t['level']==2]),'source_h3':len([t for t in toc if t['level']==3]),'external_assets':0,'algorithm_changes':0,'model_calls':0},ensure_ascii=False,indent=2))
print('Generated V5_IMPLEMENTATION_PLAN.html; sections',len([t for t in toc if t['level']==2]))
